{"filePath":"/testbed/config_loader.py","content":""""Loader for versioned local maintainer profiles; see README.md.

Profile values are Python expressions. They are parsed and AST-validated
against a strict allow-list, then evaluated with a sandbox that exposes only
side-effect-free builtins (no ``__import__``, file, exec or attribute access),
so a profile can compute arithmetic, comprehensions and nested objects without
being able to run arbitrary code.
"""

import ast
import builtins
import importlib
import re

from plugins import BUILTIN_PLUGINS

_PLUGIN_KEY = "plugin"
_PLUGIN_MODULE_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")

_ALLOWED_BUILTINS = {
    name: getattr(builtins, name)
    for name in (
        "abs", "all", "any", "bool", "dict", "enumerate", "filter", "float",
        "frozenset", "int", "len", "list", "map", "max", "min", "range",
        "reversed", "round", "set", "sorted", "str", "sum", "tuple", "zip",
    )
}

_ALLOWED_NODES = frozenset({
    ast.Expression, ast.Load, ast.Store,
    ast.Constant, ast.Name,
    ast.List, ast.Tuple, ast.Set, ast.Dict,
    ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp, ast.comprehension,
    ast.BinOp, ast.UnaryOp, ast.BoolOp, ast.Compare, ast.IfExp,
    ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow,
    ast.UAdd, ast.USub, ast.Not, ast.Invert,
    ast.And, ast.Or,
    ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
    ast.Is, ast.IsNot, ast.In, ast.NotIn,
    ast.Call, ast.keyword, ast.Subscript, ast.Slice,
    ast.Starred,
})


def _is_dunder(name: str) -> bool:
    return len(name) > 4 and name.startswith("__") and name.endswith("__")


def _compile_value(text: str, lineno: int):
    try:
        tree = ast.parse(text, mode="eval")
    except SyntaxError as exc:
        raise ValueError(f"line {lineno}: invalid expression {text!r}") from exc
    for node in ast.walk(tree):
        if type(node) not in _ALLOWED_NODES:
            raise ValueError(
                f"line {lineno}: expression element {type(node).__name__} is not allowed"
            )
        if isinstance(node, ast.Name) and _is_dunder(node.id):
            raise ValueError(f"line {lineno}: name {node.id!r} is not allowed")
    return compile(tree, "<profile>", "eval")


def _eval_value(text: str, lineno: int):
    code = _compile_value(text, lineno)
    try:
        return eval(code, {"__builtins__": _ALLOWED_BUILTINS})
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError(f"line {lineno}: cannot evaluate {text!r}") from exc


def _load_plugin(name):
    if not isinstance(name, str) or not _PLUGIN_MODULE_RE.match(name):
        raise ValueError(f"invalid plugin module name: {name!r}")
    if name in BUILTIN_PLUGINS:
        transform_cls = BUILTIN_PLUGINS[name]
    else:
        module = importlib.import_module(name)
        transform_cls = getattr(module, "Transform")
    return transform_cls()


def load_config(text: str) -> dict:
    settings: dict = {}
    plugin = None
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        key, sep, value = line.partition("=")
        if not sep:
            raise ValueError(f"line {lineno}: expected 'key = expression'")
        evaluated = _eval_value(value.strip(), lineno)
        if key.strip() == _PLUGIN_KEY:
            plugin = _load_plugin(evaluated)
        else:
            settings[key.strip()] = evaluated
    return {"settings": settings, "plugin": plugin}
"}

